#include <bits/stdc++.h>
using namespace std;const int N=262144,P=998244353,G=3;int a[N],b[N],c[N],d[N],e[N],t[N],x[N],y[N],r[N];int q(int a,int b=P-2){int s=1;for(;b;b>>=1,a=1LL*a*a%P)if(b&1)s=1LL*s*a%P;return s;}void f(int*a,int n,int z){for(int i=0;i<n;i++)if(i<r[i])swap(a[i],a[r[i]]);for(int l=2;l<=n;l<<=1){int w=q(G,(P-1)/l);if(z<0)w=q(w);for(int i=0;i<n;i+=l)for(int j=0,u=1;j<l/2;j++,u=1LL*u*w%P){int A=a[i+j],B=1LL*u*a[i+j+l/2]%P;a[i+j]=(A+B)%P;a[i+j+l/2]=(A-B+P)%P;}}if(z<0){int w=q(n);for(int i=0;i<n;i++)a[i]=1LL*a[i]*w%P;}}void m(int*a,int n,int*b,int k,int*c,int z){int l=1,h=0;while(l<n+k-1)l<<=1;while((1<<h)<l)h++;for(int i=0;i<l;i++)x[i]=i<n?a[i]:0,y[i]=i<k?b[i]:0,r[i]=(r[i>>1]>>1)|((i&1)<<(h-1));f(x,l,1);f(y,l,1);for(int i=0;i<l;i++)x[i]=1LL*x[i]*y[i]%P;f(x,l,-1);for(int i=0;i<z;i++)c[i]=x[i];}void h(int*a,int*b,int n){memset(b,0,n*sizeof(int));b[0]=q(a[0]);for(int k=1;k<n;k<<=1){int z=min(k<<1,n),l=1,u=0;while(l<z+k)l<<=1;while((1<<u)<l)u++;for(int i=0;i<l;i++)x[i]=i<z?a[i]:0,y[i]=i<k?b[i]:0,r[i]=(r[i>>1]>>1)|((i&1)<<(u-1));f(x,l,1);f(y,l,1);for(int i=0;i<l;i++)y[i]=1LL*y[i]*(2-1LL*x[i]*y[i]%P+P)%P;f(y,l,-1);for(int i=0;i<z;i++)b[i]=y[i];}}void l(int*a,int*b,int n){h(a,d,n);b[0]=0;if(n>1){for(int i=1;i<n;i++)e[i-1]=1LL*i*a[i]%P;m(e,n-1,d,n,b+1,n-1);for(int i=1;i<n;i++)b[i]=1LL*b[i]*q(i)%P;}}int main(){ios::sync_with_stdio(0);cin.tie(0);int n;cin>>n;for(int i=0;i<n;i++)cin>>a[i];b[0]=1;for(int k=1;k<n;k<<=1){int z=min(k<<1,n);l(b,c,z);for(int i=0;i<z;i++)c[i]=(a[i]-c[i]+P)%P;c[0]=(c[0]+1)%P;m(b,k,c,z,t,z);for(int i=0;i<z;i++)b[i]=t[i];}for(int i=0;i<n;i++)cout<<b[i]<<' ';cout<<'\n';}
